static void ladder_exit_update(ShTown *town, ShSavegame *save, const ShInputState *input, float dt)
{

    
    if (sh_input_down(input, KEY_START) &&
        town->step >= 3 && town->step < 5)
    {
        (town->fade_speed = 3.0f);
        step_set(town, -1);
    }

    switch (town->step)
    {
        case 0:
            (town->controls_locked = true);
            step_set(town, town->step + 1);
        /* fall through */

        case 1:
            step_set(town, town->step + 1);
            break;

        case 2:
            
            ladder_camera(town, false, -231055, -23224, -226877);
            ladder_camera(town, true, -231014, -7659, -221839);

            
            town->school.ladder_player.position.vy = -9420;
            town->school.ladder_player.rotation.vy = 0;

            ladder_fade(town, 0, false, 6144);
            ladder_animation(town, 88);
            step_set(town, town->step + 1);
        /* fall through */

        case 3:
            ladder_wait(town, dt, 14336);
            town->school.ladder_player.position.vy += sh_q12_mul(SH_Q12(dt), 1228);
            break;

        case 4:
            town->school.ladder_player.position.vy += sh_q12_mul(SH_Q12(dt), 1228);
            ladder_fade(town, 2, true, 6144);
            break;

        default:
            if (sh_save_event_get(save, 78))
            {
                
                town->school.ladder_player.position.vx = -245760;
                town->school.ladder_player.position.vy = 0;
                town->school.ladder_player.position.vz = -260915;
                town->school.ladder_player.rotation.vy = 0;

                sh_save_event_clear(save, 184);
                sh_save_event_clear(save, 78);
            }
            else if (sh_save_event_get(save, 81))
            {
                
                town->school.ladder_player.position.vx = -245760;
                town->school.ladder_player.position.vy = 2457;
                town->school.ladder_player.position.vz = -230604;
                town->school.ladder_player.rotation.vy = 2048;

                sh_save_event_clear(save, 185);
                sh_save_event_clear(save, 81);
            }

            ladder_fade(town, 0, false, 6144);

            
            ladder_unfreeze(town);
            ladder_finish(town);

            (void)0;
            break;
    }
}
/* func_800D8948 */
static void ladder_enter_update(ShTown *town, ShSavegame *save, const ShInputState *input, float dt)
{

    
    if (sh_input_down(input, KEY_START) &&
        town->step >= 4 && town->step < 6)
    {
        (town->fade_speed = 3.0f);
        step_set(town, -1);
    }

    switch (town->step)
    {
        case 0:
            (town->controls_locked = true);

            sh_save_event_clear(save, 82);
            sh_save_event_clear(save, 79);
            sh_save_event_clear(save, 80);

            ladder_fade(town, 0, true, 6144);
            step_set(town, town->step + 1);
        /* fall through */

        case 1:
            step_set(town, town->step + 1);
            break;

        case 2:
            ladder_fade(town, 1, true, 0);
            break;

        case 3:
            
            ladder_camera(town, false, -232407, -7249, -225812);
            ladder_camera(town, true, -227041, -22528, -223477);

            
            town->school.ladder_player.position.vx = -230768;
            town->school.ladder_player.position.vy = -9322;
            town->school.ladder_player.position.vz = -225689;
            town->school.ladder_player.rotation.vy = 0;

            ladder_fade(town, 0, false, 6144);
            ladder_animation(town, 87);

            if (town->school.ladder_point == 16)
            {
                sh_save_event_set(save, 79);
            }
            else if (town->school.ladder_point == 17)
            {
                sh_save_event_set(save, 80);
            }

            step_set(town, town->step + 1);
        /* fall through */

        case 4:
            ladder_wait(town, dt, 14336);

            
            town->school.ladder_player.rotation.vy = 0;
            town->school.ladder_player.position.vy += sh_q12_mul(SH_Q12(dt), -1228);
            break;

        case 5:
            
            town->school.ladder_player.position.vy += sh_q12_mul(SH_Q12(dt), -1228);

            ladder_fade(town, 2, true, 6144);
            break;

        default:
            
            ladder_unfreeze(town);
            ladder_finish(town);

            
            town->school.ladder_player.position.vy = 0;
            break;
        }
}
